def _dump(obj: object) -> str:
    return json.dumps(obj, ensure_ascii=False, indent=2) + "\n"


def scripts_json() -> str:
    return _dump(
        {
            "注記": f"{MARK}。会社も人も架空です。",
            "作ったタスク": MADE_BY,
            "説明": "テストで社長役のAIが言う発言の順番（SPEC 6章、F14）。社長役に渡すのは「社長役への決まり」「この台本だけの決まり」「発言」「聞かれたときの答え」と、回答表だけ。「始める状態」「状態に入れておくこと」「反映を確かめる状態」「記録の手直し」は、テストの準備が使う。",
            "回答表": "testdata/デモの会社/回答表.md",
            "社長役への決まり": COMMON_RULES,
            "台本": SCRIPTS,
        }
    )


def checks_json() -> str:
    return _dump(
        {
            "注記": f"{MARK}。社長役にも、試すツールにも渡さない。",
            "作ったタスク": MADE_BY,
            "説明": "台本ごとの SPEC の合格ラインと、出力で見ること。「出る文字」「出ない文字」は、コードで数えるときの候補。最後の物差しは、ケースを作るタスク（B4、B8、B30、B31c、M9）で決める。",
            "確かめること": CHECKS,
        }
    )


def _cell(text: str) -> str:
    return text.replace("|", "｜").replace("\n", " ")


def _ids(ids: list[str]) -> str:
    return "、".join(ids) if ids else "—"


def _check_for(name: str) -> dict:
    for check in CHECKS:
        if check["台本"] == name:
            return check
    raise KeyError(name)


def list_md() -> str:
    lines: list[str] = []
    add = lines.append
    add("# 台本の一覧（架空）")
    add("")
    add(
        "テストで社長役のAIが言う、社長から頼む・指摘する・直す発言の順番です（SPEC 6章「回答表・台本」、F14、TASKS D4）。"
        f"会社も人も架空です（{MARK}）。"
    )
    add("")
    add("- このファイルは `make_scripts.py` が作ります。手で直さず、`make_scripts.py` を直して作り直してください。")
    add("- 会社の事実の正本は `../デモの会社/回答表.md` です。台本では回答表の ID で事実を指します。台本の発言が回答表と違うのは、わざと違えた所（食い違う答えと、わざと入れた誤り）だけです。")
    add(f"- 作ったタスク：{MADE_BY}")
    add("")
    add("## ファイル")
    add("")
    add("| ファイル | 中身 | だれに渡すか |")
    add("|---|---|---|")
    add("| 台本.json | 台本ごとの始める状態、発言、聞かれたときの答え、記録の手直し | 社長役には「社長役への決まり」「この台本だけの決まり」「発言」「聞かれたときの答え」と回答表だけを渡す。ほかはテストの準備（scaffold）が使う |")
    add("| 確かめること.json | 台本ごとの SPEC の合格ラインと、出力で見ること | 社長役にも、試すツールにも渡さない |")
    add("| 台本の一覧.md | この文書。上の2つを人が読む形にしたもの | 開発とテストを作る人 |")
    add("| make_scripts.py | 中身の正本。上の3つを書く | 開発とテストを作る人 |")
    add("| check_scripts.py | 回答表・SPEC・文体の基準と照らす | 開発とテストを作る人 |")
    add("")
    add("- eval の Bash からは、プラグインの根（testdata/ を含む）が読めます（実験 E3）。確かめることを別のファイルに分けたのは、置き場を変えるとき（DESIGN 14章「正解を eval から読ませないか」、M13）に動かしやすくするためです。")
    add("")
    add("## 作り方と確かめ方")
    add("")
    add("```bash")
    add("uv run --script testdata/台本/make_scripts.py")
    add("uv run --script testdata/台本/check_scripts.py")
    add("```")
    add("")
    add("- 使うのは Python の標準のライブラリだけです。同じ中身なら、何度作っても同じバイト列になります。")
    add("- `check_scripts.py` は、合わないものがあれば終了コード1で終わります。")
    add("")
    add("## 社長役への決まり（どの台本にも当てはまる）")
    add("")
    add("回答表の先頭の「社長役への決まり」に、次を足します。")
    add("")
    for rule in COMMON_RULES:
        add(f"- {rule}")
    add("")
    add("## 台本とテストの対応")
    add("")
    add("| 台本 | 使うテスト | 案件 | 始める状態 | 発言の数 |")
    add("|---|---|---|---|---|")
    for script in SCRIPTS:
        add(
            f"| {_cell(script['名前'])} | {'、'.join(script['使うテスト'])} | {_cell(script['案件'])} | "
            f"{_cell(script['始める状態'])} | {len(script['発言'])} |"
        )
    add("")
    for index, script in enumerate(SCRIPTS, start=1):
        check = _check_for(script["名前"])
        add(f"## {index}. {script['名前']}（{'、'.join(script['使うテスト'])}）")
        add("")
        add(f"**始める状態**：{script['始める状態']}")
        add("")
        add("**状態に入れておくこと**")
        add("")
        for item in script["状態に入れておくこと"]:
            add(f"- {item}")
        add("")
        if "反映を確かめる状態" in script:
            add(f"**反映を確かめる状態**：{script['反映を確かめる状態']}")
            add("")
        if "この台本だけの決まり" in script:
            add("**この台本だけの決まり**（社長役に渡す）")
            add("")
            for rule in script["この台本だけの決まり"]:
                add(f"- {rule}")
            add("")
        if "記録の手直し" in script:
            edit = script["記録の手直し"]
            add("**記録の手直し**（テストの準備が当てる）")
            add("")
            add("| 項目 | 中身 |")
            add("|---|---|")
            for key in ("いつ", "ファイル", "直す項目", "直す欄", "直し方", "足す文"):
                add(f"| {key} | {_cell(edit[key])} |")
            add("")
        add("**発言**（社長役に渡す）")
        add("")
        add("| 番 | 区分 | いつ言うか | 発言 | 回答表 |")
        add("|---|---|---|---|---|")
        for line in script["発言"]:
            add(
                f"| {line['番']} | {_cell(line.get('区分', '—'))} | {_cell(line['いつ言うか'])} | "
                f"「{_cell(line['発言'])}」 | {_ids(line['回答表'])} |"
            )
        add("")
        add("**聞かれたときの答え**（社長役に渡す）")
        add("")
        add("| 聞かれたこと | 答え | 回答表 |")
        add("|---|---|---|")
        for answer in script["聞かれたときの答え"]:
            add(f"| {_cell(answer['聞かれたこと'])} | 「{_cell(answer['答え'])}」 | {_ids(answer['回答表'])} |")
        add("")
        add("**確かめること**（社長役にも、試すツールにも渡さない）")
        add("")
        add(f"- SPEC の合格ライン（{check['テスト']}）：{check['SPEC の合格ライン']}")
        add(f"- 流し方：{check['流し方']}")
        for key in ("計画書の値", "答えの値", "手直しの印"):
            if key in check:
                add(f"- {key}：{check[key]}")
        add("")
        add("| 発言 | 見ること | 出る文字 | 出ない文字 |")
        add("|---|---|---|---|")
        for item in check["見ること"]:
            numbers = "・".join(str(n) for n in item["発言"])
            add(
                f"| {numbers} | {_cell(item['見ること'])} | {_ids(item['出る文字'])} | {_ids(item['出ない文字'])} |"
            )
        add("")
    add("## 決めたこと（SPEC・DESIGN にない細部。作者が直してよい）")
    add("")
    for decision in DECISIONS:
        add(f"- {decision}")
    add("")
    return "\n".join(lines)


def build() -> dict[Path, str]:
    """作るファイルと、その中身。"""
    return {
        SCRIPTS_FILE: scripts_json(),
        CHECKS_FILE: checks_json(),
        LIST_FILE: list_md(),
    }


def main() -> None:
    for path, text in build().items():
        path.write_text(text, encoding="utf-8")
        print(f"書いた：{path.relative_to(HERE.parent.parent)}")


if __name__ == "__main__":
    main()
